,(7484,3,3,'‘ဒကာန်’ ရှု။',NULL)
,(7485,3,1,'‘ဒဂါ’ ရှု။',NULL)
,(7486,3,1,'‘ဂဂဳ’ ရှု။',NULL)
,(7487,3,1,'ကနကုတ်မြွေ။',NULL)
,(7488,3,4,'‘ဒဂါတ်’ ရှု။',NULL)
,(7489,3,1,'ကြမ်းပိုး။','‘ဒဂိတ်’ ရှု။')
,(7490,3,4,'ဈေးဆစ်သည်။','“ရာန်ဖျာမ္ဂး ဓဂုတ်တုဲရာန်ညိ။” = “ဈေးဝယ်လျှင် ဈေးဆစ်ပြီးဝယ်ပါ။”')
,(7491,3,16,'‘ဒဂိုန်’ ရှု။',NULL)
,(7492,3,1,'သစ်ပင်အၚုတ်။ သစ်ၚုတ်။','‘ဒဂဵု’ ရှု။')
,(7493,3,4,'(ကြက်၊ ငှက်စသည် တောင်ပံကိုဖြန့်၍) အုပ်ကာသည်။','“ညာတ်ဆစာၚ်ဗြဴ၊ ဗြုတဴကြံကြ။ ဓဂြလဝ်သၞေၚ်၊ တၟာပြေၚ်ဟွံက။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ပြင်းထန်စွာအော်မြည်နေသော ကြက်မကိုသာမြင်၏။ ကျွဲပမာဏမက အတောင်ဖြန့်အုပ်ကာထား၏။”')
,(7494,3,1,'သကြား။','‘သဂြာ’ ရှု။')
,(7495,3,4,'ဖမ်းသည်။','ဗ္ဂဲဓဂြီုကၞိ = ကြောင်က ကြွက်ကိုဖမ်းသည်။')
,(7496,3,1,'တောင်ဝှေး။','‘ဒစုန်’ ရှု။')
,(7497,3,4,'ပူဆွေးသည်။ ဆင်းရဲပူပန်သည်။ ပူလောင်ခံစားရသည်။','“ဓဇဳဓဇောတ်၊ ရမတ်ဖက်နှဴ။ ဟွံတီပုၚ်သွ၊ လီုစိတ္တဇဴ။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “ဆင်းရဲပူပန်၍ မျက်ရည်ယို၏။ ထမင်းဟင်းမစားနိုင်လောက်အောင် စိတ်ပျက်၏။”')
,(7497,3,4,'ပူဆွေးသည်။ ဆင်းရဲပူပန်သည်။ ပူလောင်ခံစားရသည်။','“နွံဆဒးအာဒုၚ်ဒဒိုက်အပဲါပန် ဒဒိုက်ဒဇဳဒဇတ်လောန်ရ။” (ဓမ္မဝိဘာဂ။ ပြကိုဟ်မန်ဍုၚ်သေံ။) = “အပါယ်လေးဘုံ­ ဆင်းရဲခါးသီးသောဒုက္ခကို သွားခံရန်သာရှိတော့မည်။”')
,(7497,3,4,'ပူဆွေးသည်။ ဆင်းရဲပူပန်သည်။ ပူလောင်ခံစားရသည်။','“သီုမဓဇဳဓဇတ် သၟတ်ဗြဴဒးဒုၚ်ဒဒိုခ် ပ္ဍဲသ္ၚိညးရ။” (သၠပတ်ပေါရဏာံ။ အစွောံ။) = “ထိုသူငယ်မသည် ဆင်းရဲပင်ပန်းစွာ သူတစ်ပါးအိမ်­ ဒုက္ခခံရ၏။”')
,(7497,3,4,'ပူဆွေးသည်။ ဆင်းရဲပူပန်သည်။ ပူလောင်ခံစားရသည်။','“ဒဇဳဒဇတ်၊ ရမတ်ပြဟ်နှဳ။” (လိက်သောဝါနနဟောၚ်) = “ဆင်းရဲပူပန်၍ မျက်ရည်ယိုစီးကျရ၏။”')
,(7498,3,4,'‘ဒဇူ’ ရှု။',NULL)
,(7499,3,1,'‘ဒဇဲ’ ရှု။',NULL)
,(7500,3,4,'‘ဒဇက်’ ရှု။',NULL)
,(7501,3,1,'ဆတ်သွားပင်။',NULL)
,(7502,3,1,'သဇင်ပန်း။','“ဂဇေၚ်သ္ဇေၚ်ထောဲ၊ လပေဲါပြာထာ။” (လိက်ရတနပဇ္ဇောတ)')
,(7503,3,4,'စိမ့်သည်။','ၜိုဟ်ဓဇောတ် = စိမ့်ပြီးချမ်းသည်။')
,(7503,3,4,'စိမ့်သည်။','ဂိဓဇောတ် = အရိုးစိမ့်အောင်နာသည်။')
,(7503,3,4,'စိမ့်သည်။','“ၜိုဟ်သိုဟ်ဒဇောတ်၊ ဒဵုၜဝ်ဇုတ်ပ္ညဳ။” (လိက်ဝိဓူရ) = “ရိုးတွင်းခြင်ဆီအထိကိုစိမ့်အောင် ချမ်းအေးသည်။”')
,(7504,3,1,'ခြေသုတ်။','(ကြိ) သုတ်သည်။')
,(7504,3,1,'ခြေသုတ်။','ဓဇိုတ်ဇိုၚ် = ခြေသုတ်သည်။')
,(7505,3,16,'‘ဒဇန်’ ရှု။',NULL)
,(7506,3,1,'‘ဒဇိပ်’ ရှု။',NULL)
,(7507,3,4,'ခုတ်စဉ်းသည်။','(န) စဉ်းကော။')
,(7507,3,4,'ခုတ်စဉ်းသည်။','‘ဒဇီ’ ရှု။')
,(7508,3,1,'ကစော်ရည်။ စိမ်ရည်။',NULL)
,(7509,3,1,'သပွတ်ပင်။ သပွတ်သီး။',NULL)
,(7510,3,4,'‘ဒည’ ရှု။',NULL)
,(7511,3,4,'ညိတ်သည်။','‘ဒညိက်’ ရှု။')
,(7512,3,4,'လည်ကိုဆန့်သည်။',NULL)
,(7513,3,4,'မာန်ဖီသည်။','“ဇာတ်ဂမျိသီုမသုန်၊ ဓညန်မံၚ်ဇရေၚ်ဂှ်။” (လိက်မၚ်ဗၠာဲသ္ၚိတူ) = “အဆိပ်ရှိသောမြွေငါးကောင်စလုံးသည် ထိုအနီးအပါး­ မာန်ဖီနေကြကုန်၏။”')
,(7514,3,1,'ကြောင်ပန်းရွက်။','‘ဒညောဝ်’ ရှု။')
,(7515,3,4,'ထုသည်။ ရိုက်သည်။',NULL)
,(7516,3,4,'သနသည်။ ယုတ်ညံ့သွားသည်ဟု မှတ်ထင်ခံစားရသည်။','“ဂွံလဝ်ဂဝံခိုဟ်ဟ်တုဲ ဂၠောန်ဒးသၟဝ်တေၚ်ဂၞိန်မ္ဂး ဓနအာရောၚ်။” = “အဆောင်ကောင်းကောင်းရထားပြီး ထမီတန်းအောက်လျှိုမိလျှင် သနသွားလိမ့်မည်။”')
,(7516,3,4,'သနသည်။ ယုတ်ညံ့သွားသည်ဟု မှတ်ထင်ခံစားရသည်။','“ဒွံဝတ္ထုမဟွံသ္အး ဓနအာ။” (ဇ—၇၁။ အစွောံ။) = “မသန့်သောဝတ္ထုနှင့် ထိမိသဖြင့် သနသွားသည်။”')
,(7516,3,4,'သနသည်။ ယုတ်ညံ့သွားသည်ဟု မှတ်ထင်ခံစားရသည်။','(ပါ) (န) ပစ္စည်းဥစ္စာ။ ဓနဥစ္စာ။')
,(7517,3,10,'(န) (သဒ္ဒါ) အင်အားစိုက်ထုတ်၍ အသံတင်းတင်း ရွတ်ဆိုရသောအက္ခရာ။ သံတင်းအက္ခရာ။ ဓနိတအက္ခရာ။','‘သိထိလအက္ခရ’ လည်းရှု။')
,(7518,3,1,'ပျဉ်းမပင်။','(ပါ) (နဝိ) ချမ်းသာကြွယ်ဝသော။')
,(7519,3,1,'အိပ်စက်ရာနေရာ။','“ညံၚ်ကာလသန်ၛာသၟဝ်တ္ၚဲ သတ္တံဂမၠိုၚ် မမှတ်စဴဋ္ဌာန်ဓနဳအိုတ်ရ။” (ဇ—ဝိဓုရ။ အစွောံ။) = “နေဝင်ဆည်းဆာအချိန်­ သတ္တဝါတို့သည် အိပ်စက်ရာနေရာသို့ ပြန်ကြကုန်၏။”')
,(7520,3,1,'နားနေရာစခန်း။ စခန်းချရာနေရာ။','“ခါမစိုပ်ဓနဳဓနက်ဗဒိုပ် ဖဍာန်တဏာဲဓနိက် (၄) ဒိုဟ် တရိုဟ်ကဵုစဵုဗိုၚ်တၟံဗဒိုပ်။” (အကြီုရာဇာဓိရာဇ်) = “နားနေရာစခန်းသို့ ရောက်သောအခါ စခန်းတိုင်း­ ဗိတာန်၊ ကနုတ်ပန်း၊ တင်းတိမ်တို့ကို လေးဘက်လေးတန် ပတ်ဝန်းကာရံစေ၏။”')
,(7521,3,1,'အင်္ဂါရပ်နှင့်ပြည့်စုံသော ဓါနဳ (ဋ္ဌာနဳ) ကြီးလေးရပ်။ (မွန်ဘာသာတွင် ‘ဓါနဳ’ ဟုမရေး၊‘ဓနဳ’ ဟုသာရေးသည်။ ၄င်းတို့မှာ— (၁) ရာဇာဓနဳဟုခေါ်သော မြတ်သောမင်းမျိုးနွယ်နှင့် ပြည့်စုံသောအရပ်။ (၂) ဗိတ်ဒျာဓနဳဟုခေါ်သော အတတ်ပညာရပ်များနှင့် ပြည့်စုံသောအရပ်။ (၃) ရတ္တဓနဳဟုခေါ်သော ရွှေငွေရတနာများနှင့် ပြည့်စုံသောအရပ်။ (၄) ယောဓါဓနဳဟုခေါ်သော သူရဲသူခက်သူရဲကောင်းများနှင့် ပြည့်စုံသောအရပ်။ (ဤသည်မှာ ဝေါဆရာတော်ရေးသော ‘လိက်နဲယသမုဒ္ဒြဳ’ အမည်ရသောပျို့ကဗျာကျမ်းနှင့် (မာံရောဂေါ) ရေးသော ‘လိက်သောဝိန်ဇဲယ’ အမည်ရှိမွန်ပျို့ကဗျာမှလာသော ဖွင့်ဆိုချက်ဖြစ်သည်။)','“သာ်တၟေၚ်ပၠန်၊ ဓနဳပန်ဂှ်။ ရာဇာဓနဳ၊ မွဲခုတ်ပ္ညဳသၟဟ်။ ဗိတ်ဒျာဓနဳ၊ ၜါခုတ်ပ္ညဳပြဟ်။ ရတ္တဓနဳ၊ ပိတဝဳမြဟ်။ ယောဓါဓနဳ၊ ပန်ဟီုပ္ညဳတွံ။ ဝွံတၟေၚ်ဒဒှ်၊တွံဓနဳပန်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။)')
,(7522,3,12,'(န) ဓနုရာသီ။ (ဆယ့်နှစ်ရာသီတွင် လေးစွဲယောကျာ်းရုပ်ဖြင့် မှတ်အပ်သော နဝမရာသီ။)',NULL)
,(7523,3,11,'(န) အသူရာမည်သောဘီလူး။ ဒါနောရက္ခိုသ်။','“ဓနဴတံဝွံ လုပ်လၟိဟ်ကလော်ရ။” (ဇ—၄၃၆။ အစွောံ။) = “ဒါနောရက္ခိုသ်တို့သည် ဘီလူးစာရင်းဝင်၏။”')
,(7523,3,11,'(န) အသူရာမည်သောဘီလူး။ ဒါနောရက္ခိုသ်။','“ရသိယောဂဳကၠာ၊ဓနဴလ္တူအကာသ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ရသေ့၊ ဇော်ဂျီနှင့် အာကာသထက်မှ ဒါနောရက္ခိုသ်ဘီလူး။”')
,(7524,3,1,'၁။ နယ်ကြားမှတ်တိုင်။','ပယျဵုဓနက် = နယ်ကြား။ နယ်နိမိတ်။')
,(7524,3,1,'၁။ နယ်ကြားမှတ်တိုင်။','၂။ ကျော့ကွင်း။')
,(7524,3,1,'၁။ နယ်ကြားမှတ်တိုင်။','ပံါဓနက် = ကျော့ကွင်းထောင်သည်။')
,(7524,3,1,'၁။ နယ်ကြားမှတ်တိုင်။','“လၟအာပံါဓနက် ကေတ်သၟိၚ်မြာ်ထဝ်။” (ဇ—၁၅၉။ အစွောံ။) = “မုဆိုးသည် ရွှေဥဒေါင်းမင်းကို ဖမ်းယူရန် ကျော့ကွင်းထောင်၏။”')
,(7524,3,1,'၁။ နယ်ကြားမှတ်တိုင်။','“လၟမွဲညာတ်ဂၠံၚ်ဒြာဲထဝ်မကွာ်ဂှ်တုဲ နဇုက်လောတ်စၞာံဂှ် ဍေံပံါလဝ်ဓနက်ရ။” (ဇ—၃၅၉။ အစွောံ။) =“တယောက်သောမုဆိုးသည် ရွှေသမင်သွားသောလမ်းကိုမြင်၍ သားရေလွန်ကြိုးဖြင့် ကျော့ကွင်းထောင်ထား၏။”')
,(7524,3,1,'၁။ နယ်ကြားမှတ်တိုင်။','“(လၟဂှ်) ဟွံဂွံစၟဳစၟတ်သတ်တုဲ ပံါလဝ်ဒၞက်ရ။” (ဇ—၃၉၉။ အစွောံ။) = “ထိုမုဆိုးသည် သားကောင်တို့ကို မစစ်ဆေးမူဘဲ ကျော့ကွင်းကိုထောင်၏။”')
,(7524,3,1,'၁။ နယ်ကြားမှတ်တိုင်။','(ကြိ) ကျော့ကွင်းထောင်ဖမ်းသည်။')
,(7524,3,1,'၁။ နယ်ကြားမှတ်တိုင်။','“ဂၠာဲဓနက်စိၚ်ဒြၚ်ပိဂှ်လေဝ် ဟွံဆဵု။” (အကြီုရာဇာဓိရာဇ်) = “အစွယ်သုံးချောင်းရှိသောဆင်ကို ရှာဖမ်းသော်လည်း မတွေ့။”')
,(7525,3,1,'ဒညင်းသီး။','ဓနေၚ်ကၞာဲ = ဒညင်းသီးအကြီးစား။')
,(7525,3,1,'ဒညင်းသီး။','ဓနေၚ်ဂစေမ် = ဒညင်းသီးအသေးစားမျိုး။')
,(7526,3,1,'စဉ်းတီတုံး။ စဉ်းနှီးတုံး။','‘ဒနန်')
,(7526,3,1,'စဉ်းတီတုံး။ စဉ်းနှီးတုံး။','ဒၞန်’ ရှု။')
,(7527,3,1,'‘ဒနပ်','ဒၞပ်’ ရှု။')
,(7528,3,1,'အသိုက်အမြုံ။ အိပ်တန်း။','တိုန်ဓနီ = (တိရစ္ဆာန်များ) အိပ်တန်းတက်သည်။')
,(7528,3,1,'အသိုက်အမြုံ။ အိပ်တန်း။','“သတ်ဂြိုပ်ကၠံလ္ၚီ၊ စဴဒနီဒၞာဲ။ သပဝ်စဴစိုပ်၊ ဂြိုပ်ကြိက်မဆာဲ။” (လိက်မေဃသန်) =“အရာအထောၚ်မကသော တောတွင်းတိရစ္ဆာန်တို့သည် နေရာအသိုက်အမြုံသို့ ပြန်ကြကုန်၏။ဂဠုန်သည်လည်း တင့်တယ်သောလက်ပံတောသို့ ပြန်ရောက်လေ၏။”')
,(7528,3,1,'အသိုက်အမြုံ။ အိပ်တန်း။','“စၟတ်သမ္တီကေတ် စာၚ်တိုန်စှ်ေဒနိမ်ကီု။” (မုနိန္ဒဒေသနာ) = “ကြက်အိပ်တန်းတက်ဆင်းသည်ကို မှတ်သား၍၄င်း။”')
,(7528,3,1,'အသိုက်အမြုံ။ အိပ်တန်း။','“ဂဍာ်ပဝ်စဴ၊ ကွဴသီုကဝှ။ မှတ်ဒၞာဲဓနီ၊ ဟွံတီနန္တ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ကျီးကန်း၊ ဥသြနှင့်လင်းဝက်တို့သည် ပျံသန်း၍ပြန်ကာ အိပ်တန်းနေရာသို့ အားထုတ်သွားကြသည်မှာ မရေမတွက်နိုင်အောင်ရှိ၏။”')
,(7528,3,1,'အသိုက်အမြုံ။ အိပ်တန်း။','“စာၚ်တိုန်ဓနီ၊ ဂြဴပ္တီအခါ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ကြက်သည် အိပ်တန်းတက်၍တွန်ကာ အချိန်အခါကိုသိစေ၏။”')
,(7528,3,1,'အသိုက်အမြုံ။ အိပ်တန်း။','(ကြိ) ၁။ ပေကတ်ကတ်နိုင်သည်။')
,(7528,3,1,'အသိုက်အမြုံ။ အိပ်တန်း။','“ချေံဏအ်ဓနီကွေံကွေံရ။” = “ဤမြင်းသည် အလွန်ပေကတ်သည်။”')
,(7528,3,1,'အသိုက်အမြုံ။ အိပ်တန်း။','“တြုံဇမိက်ဗ္ငမွဲ ပတၠဂၠဴမွဲစၞာဲဓၞီလောန်။ တြုံဂှ် တၞဟ်နဝေတ်ဗ္တောန်ဂၠဴဂှ် ဟွံသၟဟ်ရထ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “တစ်ယောက်သောလယ်သမားယောကျာ်း­ ပေကတ်ကတ်နိုင်သော နွားတစ်ကောင်ရှိ၏။ ထိုယောကျာ်းသည် ထိုနွားကို ဆုံးမခြင်းငှာမတတ်နိုင်။”')
,(7528,3,1,'အသိုက်အမြုံ။ အိပ်တန်း။','၂။ (အလုပ်တာဝန်ကို) ရှောင်ဖယ်သည်။ ရေသာခိုသည်။ ခေါင်းရှောင်သည်။')
,(7529,3,1,'အိပ်မွေ့သီး။',NULL)
,(7530,3,1,'ဖနောင့်။','ဓနေဟ်ဇိုၚ် = ခြေဖနောင့်။')
,(7530,3,1,'ဖနောင့်။','“ဇုတ်ဓနေဟ်ၜါ၊ ဟွံဂွံမှာခၠန်။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “ဖနောင့်ရိုးနှစ်ခုသည် အမှန်မလွဲရှိ၏။”')
,(7531,3,1,'ဂုံညင်း။','ဝေၚ်ဓနေအ် = ဂုံညင်းကစားသည်။')
,(7532,3,1,'ဒူးခေါင်း။','“ဇုတ်ဓနေအ်က္ၜံၚ်၊ ဆက်မံၚ်ၜါတန်။” (လိက်ဇမ္ဗူပတိ။မာံဒေံဍောတ်။) = “ဒူးခေါင်းရိုးသည် နှစ်တန်ဆက်နေ၏။”')
,(7533,3,4,'တွေ့ဆုံသည်။','‘ဂဗ')
,(7533,3,4,'တွေ့ဆုံသည်။','ဒဗ’ ရှု။')
,(7534,3,4,'‘ဂဗး’ ရှု။',NULL)
