,(7536,3,4,'ကပ်သည်။','‘ဒဗာန်’ ရှု။')
,(7537,3,1,'ဗုံ။ ပတ်မ။ စည်။','‘ဒဗိုန်’ ရှု။')
,(7538,3,1,'အနည်။',NULL)
,(7539,3,4,'‘ဗဗြိုက်’ ရှု။',NULL)
,(7540,3,11,'(န) ရဟန်းတို့၏ ပရိက္ခရာရှစ်ပါးတွင် ပါသောရေစစ်။ ဓမကရိုဏ်။ (ပါဠိ—ဓမ္မကရဏ) ဓမာနူ (ဝိ','သဗဓ) ‘ဒၟာနူ’ ရှု။')
,(7541,3,4,'အနီးကပ်၍ စူးစိုက်ကြည့်သည်။','“ဍေံကျောဝ်ဓမဳ၊ စဳစောတ်ရံၚ်ပၠ။” (လိက်သၟိၚ်အသး။နန္ဒသာရ။) = “အနီးကပ်စူးစိုက်ကြည့်၍ သေချာအောင်စုံစမ်းသည်။”')
,(7541,3,4,'အနီးကပ်၍ စူးစိုက်ကြည့်သည်။','“ညာတ်မုက်ရုပ်ထဝ်၊ ဗဵုကျောဝ်ဓမဳ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ရွှေရုပ်လွှာမျက်နှာကို မြင်သည်ရှိသော် စူးစိုက်၍ကြည့်၏။”')
,(7541,3,4,'အနီးကပ်၍ စူးစိုက်ကြည့်သည်။','‘ဇၟဳရံၚ်’ ရှု။')
,(7542,3,1,'‘ဒမၚ်’ ရှု။',NULL)
,(7543,3,1,'၁။ လေမှုတ်သားရေဖားဖို။','တံၚ်ဓမုၚ် = အဂ္ဂိရပ်ထိုးသည်။')
,(7543,3,1,'၁။ လေမှုတ်သားရေဖားဖို။','၂။ မြောင်း။')
,(7543,3,1,'၁။ လေမှုတ်သားရေဖားဖို။','ဓမုၚ်ဍာ်= ရေမြောင်း။')
,(7543,3,1,'၁။ လေမှုတ်သားရေဖားဖို။','၃။ အခံ။ ခံခြင်း။')
,(7543,3,1,'၁။ လေမှုတ်သားရေဖားဖို။','‘ဒမုၚ်’ ရှု။')
,(7544,3,1,'ရက်ကန်းစင်။','‘ဒမုၚ်ယန်’ ရှု။')
,(7545,3,16,'‘ဒမံၚ်’ ရှု။',NULL)
,(7546,3,1,'ပန်းထိမ်။ ပန်းဘဲ။','‘ဒမာတ်’ ရှု။')
,(7547,3,4,'‘ဒမာန်’ ရှု။',NULL)
,(7548,3,4,'လိမ်းသည်။','ဓယိကၠေၚ် = ခေါင်းဆံပင်ကို ဆီလိမ်းသည်။')
,(7548,3,4,'လိမ်းသည်။','ကၠေၚ်ဓယိ =ခေါင်းလိမ်းဆီ။')
,(7549,3,1,'တံစက်မြိတ်။','‘ဒယူ’ ရှု။')
,(7550,3,1,'တောင်စလဲပင်။ တောင်စလဲသီး။',NULL)
