,(7552,3,4,'‘ဒယီု’ ရှု။',NULL)
,(7553,3,4,'ကျော်ကြားသည်။','“ဣတေံပြာကတ်ဓယှ်တဴရ။” (ဇ—၂ဝ၂။ အစွောံ။) = “သူသည်ထင်ရှားကျော်ကြား၏။”')
,(7553,3,4,'ကျော်ကြားသည်။','‘ဒယှ်’ ရှု။')
,(7554,3,1,'‘ဒရာ’ ရှု။',NULL)
,(7555,3,1,'စဉ့်အိုးကြီး။','‘ဇရဳ’ ရှု။')
,(7556,3,4,'လှုပ်သည်။','‘ဂရိုက်’ ရှု။')
,(7557,3,4,'(နားရွက်ကို) ကားသည်။','“(စိၚ်) ဗ္ဂေၚ်ကၠုၚ်ဒြၚ်၊ ဓရၚ်က္တောဝ်ၜါ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “ထိုဆင်သည် အစွယ်ကိုလှုပ်ရှား၍ နားရွက်နှစ်ဖက်ကိုကား၏။”')
,(7558,3,1,'‘ဒရံၚ်’ ရှု။',NULL)
,(7559,3,16,'‘ဒရေပ်’ ရှု။',NULL)
,(7560,3,1,'ကျီ။','‘ဇရာံ’ ရှု။')
,(7561,3,4,'‘ဒရီု’ ရှု။',NULL)
,(7562,3,1,'ကနစိုးသီး။',NULL)
,(7563,3,4,'တွန်းသည်။','‘ဒရိုဟ်')
,(7563,3,4,'တွန်းသည်။','ဇရိုဟ်’ ရှု။')
