,(7568,3,16,'‘ဒလိၚ်’ ရှု။',NULL)
,(7569,3,4,'ယက်ကန်းရက်ရန် ချည်ရှယ်သည်။','‘ဒလုၚ်တုတ်’ ရှု။')
,(7570,3,4,'(မျက်လုံး) ပြူးသည်။ ပြူးအောင်လုပ်သည်။','‘ဒလန်’ ရှု။')
,(7571,3,4,'‘ဒလိန်ဒလာဲ’ ရှု။',NULL)
,(7572,3,4,'‘ဂလီု’ ရှု။',NULL)
,(7573,3,4,'‘ဂလီုဍိုက်’','‘ဂလီုပ္ဍိုက်’ ရှု။')
,(7574,3,4,'‘ဒလာဲ’ ရှု။',NULL)
,(7575,3,4,'လူပါးဝသည်။ ရိုင်းပျသည်။ မိုက်ရိုင်းသည်။','“ကောန်ၚာ်ဏအ် မိမဍေံဟွံဝေတ်လဝ်တုဲ ဓလဵုခဏံၚ်ကွေံရ။” = “ဤခလေးသည် သူ့မိဘများ မဆုံးမ၊ထားသဖြင့် အလွန်ရိုင်းပျသည်။”')
,(7575,3,4,'လူပါးဝသည်။ ရိုင်းပျသည်။ မိုက်ရိုင်းသည်။','“ဟွံတီမွဲသာ်၊ စိုတ်သၟာ်ဓလဵု။” (လိက်လက္ခဏပိ) = “(နင်) ဘာတစ်ခုမျှမသိဘဲ စိတ်ထားယုတ်မာ၍ မိုက်ရိုင်း၏။”')
,(7575,3,4,'လူပါးဝသည်။ ရိုင်းပျသည်။ မိုက်ရိုင်းသည်။','“သ္ကေဝ်ကတောဝ်အဵု၊ ဒလဵုကြံကြ။” (လိက်ဝိဓူရ) = “နားခါးအောင်ပြော၍ လူပါးဝဆိုးသွမ်း၏။”')
,(7576,3,4,'‘ဒလောအ်','ဒလိုအ်’ ရှု။')
,(7577,3,1,'အလှည့်။','ဒးဓဝါ = အလှည့်ကျသည်။')
,(7578,3,4,'မြည်တမ်းသည်။ ညည်းသည်။','လရိုအ်ဓဝဴ၊ နရိုအ်ဓဝဴ = ငိုညည်းမြည်တမ်းသည်။')
,(7578,3,4,'မြည်တမ်းသည်။ ညည်းသည်။','“သီုကဵုကွိၚ်ကွိုက်၊ တိုက်ဂမြိၚ်စဴ။ လ္ၚဵုဂှ်လှ်ေ၊ ဒယှ်ေဓဝဴ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “တူရိယာများကို သိုက်မြိုက်စွာတီးခတ်လျက် ပြန်လာကြရာ အချို့ကက၍ အချို့ကသီဆိုမြည်တမ်းကြကုန်၏။”')
,(7578,3,4,'မြည်တမ်းသည်။ ညည်းသည်။','“မိၜါခုဇ္ဇာ၊ ယာံအာဓဝဴ။” (လိက်မိဍောၚ်ကှ်ေထဝ်။) = “မင်းသမီးနှင့်အထိန်းတော်မသည် ငိုညည်းမြည်တမ်း၏။”')
,(7578,3,4,'မြည်တမ်းသည်။ ညည်းသည်။','“ဝုတ်အဵုတူဆု၊ ဂၠာဲဗြုဓဝဴ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “သစ်ပင်ထက်မှ မျောက်လွှဲကျော်မျက်ကွင်းဖြူသည် အော်မြည်ညည်းနေ၏။”')
,(7578,3,4,'မြည်တမ်းသည်။ ညည်းသည်။','“ဝုတ်အဵုဓဝဴ၊ ညံၚ်ကောဂၞဴကော်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “မျောက်လွှဲကျော်မျက်ကွင်းဖြူက အော်မြည်သည်မှာ မယ့်မောင်ခေါ်သကဲ့သို့ပင်တည်း။”')
,(7579,3,1,'‘ဒဝိၚ်’ ရှု။',NULL)
,(7580,3,5,'‘ဒဝိုၚ်’ ရှု။',NULL)
,(7581,3,1,'အုံဆေး။ ကျပ်စည်းရန်ဆေး။',NULL)
,(7582,3,1,'ထားဝယ်လူမျိုး။ ထားဝယ်တိုင်းရင်းသား။','“ယခေၚ်ဓဝဲါ၊ ဂၠိုၚ်ဒၞာဲဒေသ။ ဗိက်တၞၚ်သဳ၊ ဇဳရးသဗ္ဗ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ရခိုင်နှင့်ထားဝယ်တို့သည် မြိတ်နှင့်တနင်္သာရီတိုင်းအလုံး နေရာဒေသများစွာတွင်ရှိ၏။”')
,(7583,3,4,'လွှဲသည်။','ဓဝုဲခရေၚ် = ပုခက်လွှဲသည်။')
,(7583,3,4,'လွှဲသည်။','‘ဒဝုဲ’ ရှု။')
,(7584,3,1,'လဲလူရွက်ပင်။',NULL)
,(7585,3,10,'(န) ဓါတ်တော်ကိုဋ္ဌာပနာ၍ တည်သောစေတီ။ ဓာတုစေတီ။',NULL)
,(7586,3,10,'(န) ဒြပ်စင်တို့တည်ရှိပုံ၊ ပြုမူလှုပ်ရှားပုံတို့ကို လေ့လာသောသိပ္ပံပညာရပ်။ ဓာတုဗေဒ။',NULL)
,(7587,3,11,'(န) အခက်အခဲ။ ဘေးဒုက္ခ။ ဘေးဥပဒ်။','“ခါရအဲမံၚ်ပ္ဍဲဍုၚ်ဝွံလအ် ဓိကိုရ် (၄) သာ်နာၚ်သဒှ်။ ဓိကိုရ်ပ္ဍဲဨကရာဇ် ပ္ဍဲဂၞကျာ်၊ ပ္ဍဲဍုၚ် ဟွံသေၚ် ပ္ဍဲက္ဍိုၚ်ဗ္တာၚ် (သဒှ်)” စိၚ်ဗ္တာၚ်ကဵုနိမိတ်လ္ပံ။ (အကြီုရာဇာဓိရာဇ်) = “ဤတိုင်းပြည်­ ငါကြာကြာနေလျှင် ဘေးဥပဒ်လေးမျိုးဖြစ်လိမ့်မည်။ မင်းဧကရာဇ်­၄င်း မိဖုရား­၄င်း ထီနန်း­၄င်း သို့တည်းမဟုတ် တိုင်းပြည်­၄င်းဘေးဥပဒ်ဖြစ်လိမ့်မည်။”')
,(7587,3,11,'(န) အခက်အခဲ။ ဘေးဒုက္ခ။ ဘေးဥပဒ်။','“ကြာအဲကဵုနာဲ၊ လောံလာဲကၠၚ်ပြဵု။ ပကျာ်ရံၚ်ဗဵု၊ ဓိကဵုဝွံရော။” (လိက်မေဃသန်) = “ငါနှင့်ချစ်သူသခင်ကြား ကြောင့်ကြပူပန်နေရသောဒုက္ခကို အဘယ်ကြောင့်သခင်ကြည့်နေနိုင်ရက်သနည်း။”')
,(7587,3,11,'(န) အခက်အခဲ။ ဘေးဒုက္ခ။ ဘေးဥပဒ်။','“ဂုန်အံက်နာဲဂှ်၊ မိဒှ်ဓိကဵု။” (လိက်ရာဇာဟတ္ထိ) = “သင့်ဖခင်ကြောင့် မိခင်ဘေးဒုက္ခဖြစ်ရ၏။”')
,(7587,3,11,'(န) အခက်အခဲ။ ဘေးဒုက္ခ။ ဘေးဥပဒ်။','‘အဓိကဵု’ (န) နှင့်အတူတူ။')
,(7588,3,1,'အင်ကြင်းပင်။','“ပ္ဍဲတၞံဓိတာန်မွဲ မဍိုက်ပေၚ်သီုပ္ကဴမရာၚ်ဆာဲတဴဂှ် ဂစေံကွဴမွဲဍုန်ဒၟံၚ်တုဲ။”ဇ—၂၆၉။ အစွောံ။) = “ကောင်းစွာပွင့်သော တခုသောအင်ကြင်းပင်­နားလျက် တခုသောဥသြသည်—။” (ညောင်ကန်)')
,(7588,3,1,'အင်ကြင်းပင်။','“ပ္ဍဲကာလဂှ် ဗောဓိသတ်ပိုဲ ဒှ်ဒေဝတဴ ပ္ဍဲဂြိုပ်ဟေမဝန်ကီု ဒှ်ဒေဝတဴဆုဓိတာန်။” (ဇ—၇၄။ အစွောံ။) = “ထိုအခါ ဘုရားလောင်းသည် ဟိမဝန္တာအရပ်­ တခုသောအၚ်ကြင်းတော­ ရုက္ခဇိုဝ်းနတ်၏အဖြစ်ဖြင့်ဖြစ်၏။” (ညောင်ကန်)')
,(7588,3,1,'အင်ကြင်းပင်။','“ဗောဓိသတ်ပိုဲရသိ ဂ္ဇံဒၟံၚ်အသၟဝ်တၞံဓိတာန်ဂှ်—။” (ဇ—၃၁၃။ အစွောံ။) = “ဘုရားလောင်းသည် ထိုဥယျာဉ်­ ကောင်းစွာပွင့်သော အင်ကြင်းပင်ရင်း­ (ထိုင်နေ၏။)” (ညောင်ကန်) ဓိဝါန် (န) ကန္တာရ။ တော။')
,(7588,3,1,'အင်ကြင်းပင်။','“ယွံသၟိၚ်ယက္ခိ၊ ပိုၚ်ဂြိုပ်ဓိဝါန်။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) =“တောကိုပိုင်စိုးသော အို—ယက္ခဘီလူး။”')
,(7588,3,1,'အင်ကြင်းပင်။','“စိုပ်ဂြိုပ်ဓိဝါန်၊ ဗၠးထာန်ယက္ခာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “တောသို့ရောက်၍ ယက္ခဘီလူး၏အရပ်မှ လွတ်၏။”')
,(7589,3,1,'‘ထိဝိုဟ်’ ရှု။',NULL)
,(7590,3,11,'(န) ဓူတင်။ (ကိလေသာကို ပယ်ခွါနိုင်သောအကျင့် = ဒ္ဂေတ်မကလှ်လဖှ်ကၠေံကိလေသ) (ပါဠိ—ဓုတၚ်္ဂ)',NULL)
,(7591,3,11,'(န) မြူ။ မြူမှုန့်။ ဖုန်။ (ပါဠိ—ဓူလဳ)',NULL)
,(7592,3,1,'လယ်ယာမြေ။','“ဟိုတ်ဂှ်ကြၚ်ကၠုၚ်၊ ဒေါဝ်ဓုၚ်ဝါဗ္ၚ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ထို့ကြောင့်ပၚ် ဤယာတောလယ်တောအလယ်သို့ ခြေဦးတည့်ရာသွားရင်း ရောက်လာခြင်းဖြစ်၏။”')
,(7592,3,1,'လယ်ယာမြေ။','“ဗဵုဂြိုပ်ဗဵုကြုၚ်၊ ဗဵုဝါဓုၚ်ဗ္ၚ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “တောကြည့် မြစ်ကြည့်လယ်ယာမြေကြည့်သည်။”')
,(7592,3,1,'လယ်ယာမြေ။','“ထောံဂြိုပ်ဂွံဝါ၊ ထောံဝါဂွံဓုၚ်။” (လိက်သောဝိန်ယဲဇ။ မာံရောဂေါ။) = “သစ်တောကိုစွန့်ခွာ၍ လွင်ပြင်သို့ရောက်၏၊ လွင်ပြင်ကိုစွန့်ခွာ၍ လယ်ယာမြေသို့ရောက်၏။”')
,(7593,3,11,'(နဝိ) ဖျက်ဆီးတတ်သော။ ဖျောက်ပယ်တတ်သော။','“သဘဴထဝ်တမြံၚ်ဟွံဂွံဒုၚ်လၟေတ်ဓံၚ်သဳဒမာတ် သ္ဂောံဒှ်ကယျိုၚ်ဨကရာတ်ပၠန် ဟွံမွဲသက်သက်ရ။” (သၠပတ်အနမတဂ္ဂသံသာရကထာ) = “မာကျောသောရွှေသည် ထိုမာကျောမှုကို ဖျက်ဆီးဖျောက်ပယ်တတ်သော ပန်းထိမ်ဆရာ၏ ပြုစီမံခြင်းကိုမခံဘဲ ထိုရွှေသည် မင်းဧကရာဇ်၏ အဆင်တန်ဆာဖြစ်ရိုးမရှိ။”')
,(7594,3,4,'လွှင့်ထူသည်။ ထောင်သည်။','ဓိုၚ်ယာ = ရွက်လွှင့်ထူသည်။')
,(7594,3,4,'လွှင့်ထူသည်။ ထောင်သည်။','ဓိုၚ်ကၞဴ = ခြင်ထောင်ထောင်သည်။')
,(7594,3,4,'လွှင့်ထူသည်။ ထောင်သည်။','(နဝိ) (နားရွက်) ကားသော။')
,(7594,3,4,'လွှင့်ထူသည်။ ထောင်သည်။','ကတောဝ်ဓိုၚ် = နားရွက်ကားသည်။')
,(7595,3,1,'အင်အား။','ဓတ်ချေံမသုန် = မြင်းငါးကောင်အား။')
,(7596,3,11,'(န) ၁။ (ဘုရား၊ ရဟန္တာစသည်၏) ဓါတ်တော်။','ဓါတ်ကျာ် = ဘုရားဓါတ်တော်။')
,(7596,3,11,'(န) ၁။ (ဘုရား၊ ရဟန္တာစသည်၏) ဓါတ်တော်။','“စံၚ်ကၠေံဇွပစ္စေဂဗုတ်တုဲ ဓါတ်ဂှ် ဒက်ကၠေံစေတဳတုဲ—။” (ဇ—၄၂ဝ။ အစွောံ။) =“ပစ္စေကဗုဒ္ဓာ၏အလောင်းတော်ကို မီးသဂြုÊ၍ ဓါတ်တော်ကို စေတီတည်ထား၏။”')
,(7596,3,11,'(န) ၁။ (ဘုရား၊ ရဟန္တာစသည်၏) ဓါတ်တော်။','၂။ ဓါတ်။ဓါတ်ကြီးလေးပါးကို မျှတစေသောအစာ။')
,(7596,3,11,'(န) ၁။ (ဘုရား၊ ရဟန္တာစသည်၏) ဓါတ်တော်။','ဗ္စဓါတ် = ဓါတ်စာကျွေးသည်။')
,(7597,3,4,'(ခန္ဓာအတွင်း­) ဓါတ်ချောက်ချားသည်။',NULL)
,(7598,3,4,'(ခန္ဓာအတွင်း­) ဓါတ်မညီမညွတ်ဖြစ်သည်။ သွေးလေဖောက်ပြန်သည်။','“(ဣသိဗြဴဂှ်) ပဒတဴပ္ဍဲဂြိုပ်ဟေမဝန်ဂှ် ဂၠိုၚ်ကဵုဂိတုသၞာံတုဲ ဟွံဂွံစဖၞုၚ်တုဲ ဓါတ်ဂတးအာ—။” (ဇ—၃၂၈။အစွောံ။) = “ထိုရသေ့မသည် ဟိမဝန္တာတော­ ကာလရှည်ကြာစွာနေ၍ အၚန်ဓါတ်ကို မစားရသဖြင့် ဓါတ်မညီမညွတ်ဖြစ်၏။”')
,(7599,3,4,'‘ဓါတ်ကၞုက်ကၞာဲ’ နှင့်အတူတူ။',NULL)
,(7600,3,4,'ဓါတ်ကြီးလေးပါး။','“ပထဝဳ (ဓါတ်တိ) မွဲ၊ အာပေါ (ဓါတ်ဍာ်) မွဲ၊ ဝါယော (ဓါတ်ကျာ) မွဲ၊ တေဇော (ဓါတ်ပၟတ်) မွဲ ဣဝွံဓါတ်ပန်ရ။” = “ပထဝီ (မြေဓါတ်) ၊ အာပေါ (ရေဓါတ်) ၊ ဝါယော (လေဓါတ်) ၊ တေဇော (မီးဓါတ်) တည်းဟူသော ဓါတ်ကြီးလေးပါး။”')
,(7600,3,4,'ဓါတ်ကြီးလေးပါး။','“ဓါတ်ပန်လီုအာတုဲ ယဲဂၠိုၚ်က္တဵုဒှ်ရ။” (ဇ—၅၂၁။ အစွောံ။) = “ဓါတ်ကြီးလေးပါးပျက်၍ ရောဂါများဖြစ်ပေါ်၏။”')
,(7601,3,1,'(မြတ်စွာဘုရား) ဆံတော်။','ဓါတ်သော်ဂမျိုၚ် = ဆံတော်ရှင်။')
,(7602,3,4,'(ဓါးစသည်) တုံးသည်။','“မြဏအ်ဓိုတ်အာရ။” = “ဤဓါးတုံးသွားပြီ။”')
,(7603,3,1,'ဗုံရှည်။ အိုးစည်။ ဒိုးပတ်။',NULL)
,(7604,3,1,'၁။ ကန်တော့ပွဲ။','၂။ (အနာကျပ်ထုပ်ထိုးရန်) ကျပ်ထုပ်။')
,(7604,3,1,'၁။ ကန်တော့ပွဲ။','(စည်း) အထုပ်။')
,(7604,3,1,'၁။ ကန်တော့ပွဲ။','ပၞာၚ်မွဲဓုပ် = ဖရောင်းတိုင်တစ်ထုပ်။')
,(7605,3,11,'(န) ၁။ ပြာသာဒ်အထွတ်။ ထုပိကာ။ (ပါဠိ—ထူပိကာ)','“ညးကၠောန်တမၞက်သၟိၚ်ဂှ် ဟွံဂွံစုတ်ကၟဳဏီ ဆဂွံပ္တိုန်လဝ်ဓုပ်ပြကာဂှ်ကီု။” (ဇ—၃၉၆။ အစွောံ။) = “မင်း၏နေရာအိမ်သည် အမိုးမတပ်ရသေး။ ပြာသာဒ်အထွတ်ကို တင်ထားကာမျှသာဖြစ်၏။”')
,(7605,3,11,'(န) ၁။ ပြာသာဒ်အထွတ်။ ထုပိကာ။ (ပါဠိ—ထူပိကာ)','၂။ စေတီ၏အထွတ်။')
,(7605,3,11,'(န) ၁။ ပြာသာဒ်အထွတ်။ ထုပိကာ။ (ပါဠိ—ထူပိကာ)','“ဓုပ်ပြကာကျာ်လ္ဂုၚ်။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “ရွှေတိဂုံစေတီတော်၏အထွတ်။”')
,(7605,3,11,'(န) ၁။ ပြာသာဒ်အထွတ်။ ထုပိကာ။ (ပါဠိ—ထူပိကာ)','၃။ (ဥပစာ) အထွတ်အမြတ်။ အထွတ်အထိပ်။')
,(7605,3,11,'(န) ၁။ ပြာသာဒ်အထွတ်။ ထုပိကာ။ (ပါဠိ—ထူပိကာ)','“ဒစိတ်စှ်ောအဵု၊ ကဵုဒစိတ်ကၠာ။ ဒဵုသိၚ်္ဃုတ္တ၊ ဒှ်ဓုပ်ပြကာ။” (လိက်တပူတဗဝ်) = “တောင်ကိုးဆယ့်ကိုးလုံးအနက် သိင်္ဃုတ္တရတောင်သည် အထွတ်အမြတ်ဖြစ်၏။”')
,(7606,3,1,'ထင်းရူးစေးအခိုးအိုး။','“စံၚ်ဗ္ဂဵုပၞာၚ်သ္ဍဴ၊ ဓုပ်သ္ၚဴမြမောဝ်။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “ဆီမီးကိုလည်းကောင်း ထင်းရူးစေးအခိုးအထုံအိုးကိုလည်းကောင်း ထွန်းညှိသည်။”')
,(7607,3,1,'အခိုးအထုံအိုး။','“ဓုပ်သ္ဍဴကီု ကဵုစဳရေၚ်လဝ်ရ။” (ဇ—၄ဝ၉။ အစွောံ။) = “အခိုးအထုံအိုးကိုထား၍—။” (ညောင်ကန်)')
,(7607,3,1,'အခိုးအထုံအိုး။','“မစံၚ်ပူဇဴလဝ်ဓုပ်သ္ဍဴ မကွက်လဝ်ပ္ကဴမြမောဝ်အိုတ်သီု—။” (အကြီုရာဇာဓိရာဇ်) = “အခိုးအထုံအိုးတို့ကို ထွန်းညှိပူဇော်ထားစေကုန်၍ ပန်းနံ့သာတို့ကို ချိတ်ဆွဲထားစေကုန်၏။”')
,(7608,3,10,'(န) ၁။ ဟုတ်မှန်သောတရား။','၂။ တရားဓမ္မ။ ဗုဒ္ဓ၏တရားတော်။')
,(7609,3,11,'(န) တရားဟောပုဂ္ဂိုလ်။ ဓမ္မကထိက။','“လကုဏ္ဍကဘဒ္ဒိယထေမ္ဂးဂှ် —မဒှ်ဓမ္မကထိုက်ရောၚ်။ နွံတဝှ်ဓဝ်မမိပ်ရောၚ်။” (ဇ—၂ဝ၂။ အစွောံ။) = “ လကုဏ္ဍကဘဒ္ဒိယမထေရ်သည် ဓမ္မကထိကဖြစ်၏။ သာယာစွာသောအသံဖြင့် တရားဟောတတ်၏။”')
,(7610,3,11,'(န) ရေစစ်။ ဓမ္မကရိုဏ်။ (ပါဠိ—ဓမ္မကရဏ)',NULL)
,(7611,3,11,'(န) ဓမ္မခန်။ ဓမ္မက္ခန္ဓာ။ (မြတ်စွာဘုရား ဟောတော်မူအပ်သော တရားအစုအပေါင်း။)','‘ဓမ္မက္ခန်’ နှင့်အတူတူ။')
,(7612,3,11,'(န) ဓမ္မဂုဏ်တော်။ တရားဂုဏ်တော်။','“ကဵုဂွံဗှ်ဗၞုဟ်မံၚ် ဗုဒ္ဓဂုဏ် ဓမ္မဂုဏ်သံဃဂုဏ်လၟိုန်—။” (အကြီုရာဇာဓိရာဇ်) = “ဘုရားဂုဏ်တော်၊ တရားဂုဏ်တော် သံဃာဂုဏ်တော်တို့ကို အစဉ်အောက်မေ့နေပါစေ။”')
,(7613,3,10,'(န) ၁။ ပိဋကတ်တော်လာ တရားတော်တို့ကို ဋ္ဌာပနာထားရာစေတီ။','၂။ ပိဋကတ်ကျမ်းဂန်များ။')
,(7614,3,11,'(န) ၁။ ဓမ္မစကြာတရားတော်။','၂။ တရားတော်၏ တန်ခိုးအရှိန်အစော်။')
,(7615,3,10,'(န) ဓမ္မတာ။ အလေ့သဘော။ အမြဲဖြစ်သောသဘော။ ဇာတိသဘော။','“ဒၞာဲညးမကၠောန်လဝ် ဍေံပလီုကၠေံရောၚ်။ ဣဝွံဓမ္မတာကၞုဲတံရ။” (ဇ—၂၅၇။ အစွောံ။) = “သူတစ်ပါးပြုလုပ်ထားသည်ကို ဖျက်ဆီးပစ်ခြင်းသည် မျောက်တို့၏ဇာတိသဘောဖြစ်၏။”')
,(7615,3,10,'(န) ဓမ္မတာ။ အလေ့သဘော။ အမြဲဖြစ်သောသဘော။ ဇာတိသဘော။','“ပွမဂ္ၚေၚ်သာ်ဝွံမဒှ်ဓမ္မတာကလော်ဗြဴတံဂှ်ရ။” (ဇ—၁၉၆။ အစွောံ။) = “ဤသို့လှည့်လည်ခြင်းသည် ထိုဘီလူးမတို့၏ အလေ့သဘောတည်း။”')
,(7615,3,10,'(န) ဓမ္မတာ။ အလေ့သဘော။ အမြဲဖြစ်သောသဘော။ ဇာတိသဘော။','“မၞးမဒှ်ဗြဴမဂွတုဲမဟွံဂံၚ်အာတ်ဂှ် မဒှ်ဓမ္မတာဗြဴတံရ။” (ဇ—၅၃၅။အစွောံ) = “သင်သည် မိန်းမသားဖြစ်၍ ရှက်သဖြင့်မတောင်းဝံ့ခြင်းသည် မိန်းမတို့၏ဓမ္မတာပင်တည်း။”')
,(7616,3,10,'(န) တရားအလှူ။ ဓမ္မဒါန။',NULL)
,(7617,3,16,'(န) ဓမ္မဒူတ။ တရားတမန်။ သာသနာပြုပုဂ္ဂိုလ်။',NULL)
,(7618,3,10,'(န) တရားဓမ္မဟောခြင်း။ ဟောပြောသောတရား။ ဓမ္မဒေသနာ။',NULL)
,(7619,3,11,'(န) ပုဂ္ဂိုလ်ကိုမရည်စူးဘဲ တရားသဘောကို ရည်စူးခြင်း။','‘ပုဂ္ဂလဓိဋ္ဌာန်’လည်းရှု။')
,(7620,3,10,'(န) (ဂေါတမမြတ်စွာဘုရား၏) တရားဘဏ္ဍာစိုး။ (ရှင်အာနန္ဒာ။)',NULL)
,(7621,3,10,'(န) တရားသဖြင့်စစ်ထိုးခြင်း။','“မဟောဟ်သဓကဵုဗမၞးကေဝဋ် ကဵုတဝ်စၞေဟ်ဓမ္မယုဒ္ဓမွဲကဵုမွဲ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “မဟောသဓနှင့်ကေဝဋ်ပုဏ္ဏားတို့ကို တစ်ယောက်ချင်း တရားသဖြင့်စစ်ထိုးခြင်းကို စစ်ထိုးကြစေအံ့။”')
,(7622,3,10,'(န) ၁။ တရားမင်း။ မြတ်စွာဘုရား။','၂။ တရားနှင့်အညီ အုပ်စိုးသောဘုရင်။')
,(7623,3,11,'(န) တရားရတနာ။','“ပ္ဍဲဓမ္မရတ်ဂှ် အဲသၟိက်ဂွံပပူဇဴညိ။” (ဇ—၄၉၆။ အစွောံ။) = “အကျွန်ုပ်သည် တရားရတနာအား ပူဇော်ခြင်းကို ပြုလိုပါ၏။” (ညောင်ကန်)')
,(7624,3,10,'(န) ဖြောင့်မှန်သော အယူဝါဒရှိသူ။ ဓမ္မဝါဒီ။',NULL)
,(7625,3,11,'(န) တရားနှင့်ဆိုင်သောကိစ္စ။ တရားကျင့်ဝတ်။ ဓမ္မဝတ်။','“ရာဇာဝတ်ကောံ၊ဓမ္မဝတ်ဇဳ။ လောကဝတ်စိ၊ ဝတ်ပိသၟဟ်ညဳ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ရာဇဝတ်၊ ဓမ္မဝတ်၊ လောကဝတ်ဟူသော ဝတ္တရားသုံးပါးနှင့် ပြည့်စုံညီညွတ်သည်။”')
,(7626,3,10,'(န) တရားစစ်သူကြီး။ ဓမ္မသေနာပတိ။ (ရှင်သာရိပုတ္တရာ)','‘သကိုပ်ပၞာန်ဓဝ်’၊ ‘ဒကိုပ်ပၞာန်ဓဝ်’ နှင့်အတူတူ။')
,(7626,3,10,'(န) တရားစစ်သူကြီး။ ဓမ္မသေနာပတိ။ (ရှင်သာရိပုတ္တရာ)','“ပဟိုတ်ကဵုဓမ္မသေနာပတိတုဲ ကောရဏ္ဍိယဇာတ် ကျာ်တြဲတွံ။” (ဇ—၃၅၆။ အစွောံ။) = “တရားစစ်သူကြီး (အရှင်သာရိပုတ္တရာ) ကို အကြောင်းပြု၍ ကောရဏ္ဍိယဇာတ်ကို မြတ်စွာဘုရားဟောတော်မူ၏။”')
,(7627,3,11,'(န) တရားဆုံးဖြတ်သောကျမ်း။ ဓမ္မသတ်။ (ပါဠိ—ဓမ္မသတ္တ)','‘ဓမ္မသာတ်ဝါရေဝ်ရောဝ်’ = ‘ဝါရီရူဓမ္မသတ်’')
,(7627,3,11,'(န) တရားဆုံးဖြတ်သောကျမ်း။ ဓမ္မသတ်။ (ပါဠိ—ဓမ္မသတ္တ)','ဓမ္မသာတ်မနုရသိ = မနုဓမ္မသတ်။ (မဟာသမ္မတမင်းလက်ထက်က အသုံးပြုသော မနုရသေ့စီရင်သည့်ဓမ္မသတ်။)')
,(7627,3,11,'(န) တရားဆုံးဖြတ်သောကျမ်း။ ဓမ္မသတ်။ (ပါဠိ—ဓမ္မသတ္တ)','“ဗောဓိသတ်လေဝ် နလၟေၚ်ပရေၚ်သၞောဝ်ဓမ္မသာတ်တံဂှ် ကဵုညးချူလဝ်ကဵုဗပိုတ်တုဲ—။” (ဇ—၃၈၈။ အစွောံ။) = “ဘုရားလောင်းသည် တရားဥပဒေဓမ္မသတ်တို့ကို ပေပုရပိုက်­ ရေးသားထားစေ၏။”')
,(7627,3,11,'(န) တရားဆုံးဖြတ်သောကျမ်း။ ဓမ္မသတ်။ (ပါဠိ—ဓမ္မသတ္တ)','“သၟိၚ်ဟီုတိုန်ကၠာ၊ ကဵုသေဏာရ။ မၞးတအ်စဳရေၚ်၊ လၟေၚ်ဓမ္မ။ တိုၚ်ရာဇာသာတ်၊ ဓမ္မသာတ်ဂျ။ — ပဝေဏဳကၠာ၊ ညးတမၠာပၠ။ ဂစိုတ်ထောံဍေံ၊ ဟွံဒးပြဝ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “မင်းသည် သေနာပတိအားဆို၏၊ တရားနှင့်အညီ ရာဇသတ်ပြစ်မှုဥပဒေအရ၄င်း ဓမ္မသတ်ဥပဒေအရ၄င်း ရှေးသူတို့၏ထုံးတမ်းစဉ်လာအတိုင်း သင်တို့စီရင်ကြကုန်လော့။ သူ့ကိုသတ်ပစ်ရန် မလျောက်ပတ်။”')
,(7628,3,10,'(န) ၁။ ပါဠိ၊ အဋ္ဌကထာစသည်ကို သင်ကြားပို့ချရေသာဆရာ။','၂။ စာချတန်းစာမေးပွဲအောင်မြင်သူ။')
,(7629,3,11,'(န) တရားအာရုံ။ ဓမ္မာရုံ။',NULL)
,(7630,3,10,'(န) တရားသဖြင့် ရှာဖွေရရှိသောပစ္စည်း။ ဓမ္မိယလဒ္ဓ။',NULL)
,(7631,3,11,'(န) မြတ်စွာဘုရားဟောတော်မူအပ်သော တရားအစုအပေါင်း။ ဓမ္မက္ခန္ဓာ။',NULL)
,(7632,3,4,'‘ဒမြဴ','ဒရဴ’ ရှု။')
,(7633,3,4,'(ကျယ်လောင်သော) အသံပြုသည်။ မြည်ဟည်းသည်။',NULL)
,(7634,3,1,'ကြေးဝါ။','“ယွံမဒ္ဒဳ၊ အဲသလှ်ေဂးထဝ်ဥုရကိုတ်ရောၚ် အဲဝေသန္တဝ်မလဝ်စိုတ်၊လၟုဟ်ဝွံစဴဒှ်ဓမြိုတ်အပြောံရောၚ်သွံမဒ္ဒဳ” သၟိၚ်ဝေသန္တဝ်ဂး။ (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “အဘယ်မဒ္ဒီ၊ သင့်ကို တောက်ပသောရွှေစင်ဟု ငါထင်မြင်မှတ်ယူခဲ့၏။ ယခုမူကား သင်သည် သာမန်အညံ့စားကြေးမျှသာတည်း” ဟု ဝေဿန္တရာမင်းဆို၏။')
,(7634,3,1,'ကြေးဝါ။','“သၠာ်သၠုဲဓမြိုတ်၊ ဍိုတ်တၟံဟွံသေၚ်။” (လိက်ပယးအနိစ္စ)')
,(7634,3,1,'ကြေးဝါ။','‘ဗမြိုတ်’')
,(7634,3,1,'ကြေးဝါ။','‘ဒမြိုတ်’ နှင့်အတူတူ။')
,(7635,3,1,'မျက်စိတစ်မှိတ်။','‘ဒမြိပ်မတ်’ ရှု။')
,(7636,3,1,'ဓါးပြ။','‘ဓမၠမွဲဂှ် ညးရပ်ဂွံတုဲ—။’ (ဇ—၁၉၃။ အစွောံ။) = ‘ဓါးပြတစ်ယောက်ကို လူများဖမ်းမိ၍—။’')
,(7636,3,1,'ဓါးပြ။','‘ဒမၠ’ ရှု။')
,(7637,3,1,'မန်းမှုတ်သောဂါထာ။','“ပွမမန်ဗဂိုဟ်မန်ယန်ဂြန်ဓါမ်ဂါထာ။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) = “ဂါထာမန္တရားကို မန်းမှုတ်ခြင်း။”')
,(7638,3,4,'၁။ အုံ့ဆိုင်းသည်။ ညို့မှိုင်းသည်။','တ္ၚဲဓီု = နေရောင်မှိန်သည်။')
,(7638,3,4,'၁။ အုံ့ဆိုင်းသည်။ ညို့မှိုင်းသည်။','၂။ ဉာဏ်ထိုင်းသည်။နုံ့သည်။ ပညာနုံ့သည်။')
,(7638,3,4,'၁။ အုံ့ဆိုင်းသည်။ ညို့မှိုင်းသည်။','“ကွးဘာဂှ်မွဲ ညာဏ်ဓီုကွေံရ။” = “ထိုကျောင်းသားသည် တကယ်ဉာဏ်နုံ့သည်။”')
,(7638,3,4,'၁။ အုံ့ဆိုင်းသည်။ ညို့မှိုင်းသည်။','“ဟာဲမာသမၠီု၊ ဓီုသန်သွံမ။” (လိက်ထေအနန်) = “ဟယ်မာရ်နတ်မိုက်၊ သင်သည် အလွန်ပညာနုံ့လေစွတကား။”')
,(7639,3,4,'တွေဝေထုံထိုင်းသည်။ မိုက်မဲသည်။ လိမ္မာပါးနပ်ခြင်းမရှိ။','“သမၠီုသ္ဓီုသ္ဓုဲ၊ သ္အိုပ်သ္အုဲသ္အဟ်သ္အေၚ်။” (လိက်ဝိဓူရ) = “သူမိုက်သည် ဉာဏ်တုံးထုံထိုင်းညံ့ဖျင်း၏။”')
,(7639,3,4,'တွေဝေထုံထိုင်းသည်။ မိုက်မဲသည်။ လိမ္မာပါးနပ်ခြင်းမရှိ။','“ဓီုဓုဲပညာ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ပညာနုန့်သည်။”')
,(7639,3,4,'တွေဝေထုံထိုင်းသည်။ မိုက်မဲသည်။ လိမ္မာပါးနပ်ခြင်းမရှိ။','“မိဒ္ဓဓကုဲ၊ ဓီုဓုဲဒှ်အာ။ ဝိစိကိစ္ဆာ၊ သၚ်ကာဒှ်ရ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “မိဒ္ဓသည် ငိုက်မျဉ်းခြင်း တွေဝေထုံထိုင်းခြင်းဖြစ်၍ ဝိစိကိစ္ဆာသည် ယုံမှားခြင်းဖြစ်၏။”')
,(7639,3,4,'တွေဝေထုံထိုင်းသည်။ မိုက်မဲသည်။ လိမ္မာပါးနပ်ခြင်းမရှိ။','“ဓီုဓုဲလောန်ဗၞတ်၊ ကတ်ဟွံဂွံဂျ။” (လိက်ခဂ္ဂေါဟတ္ထဇဲယကုမ္မာ) = “အလွန်အမင်းထုံထိုင်း၍ အတတ်သၚ်၍မရ။”')
,(7640,3,4,'ထုံထိုင်းသည်။ ညာဏ်ထိုင်းသည်။ ထူအသည်။','“ဝေဏဳဗြဴအဲဝွံ ဓီုၜီုတုဲ—။” (ဇ—၄၃၇။အစွောံ။) = “ငါ့မယားဝေဏီသည် ထူအထုံထိုင်း၏။”')
,(7640,3,4,'ထုံထိုင်းသည်။ ညာဏ်ထိုင်းသည်။ ထူအသည်။','“ယွံတၠအဲ၊ ဒဒှ်ပတိဘာန်ဟွံမွဲတုဲ ဓီုၜိုမ်ဂှ် တၠအဲရောၚ်မဒှ်သွံ။” (ဇ—၄၃၇။ အစွောံ။) = “ငါ့ရှင်၊ သင်သည်သာလျှင် ဉာဏ်ပညာမရှိ၍ထုံထိုင်းထူအ၏။”')
,(7641,3,12,'(န) ၁။ တရား။','ဓဝ်မေတ္တာ = မေတ္တာတရား။')
,(7641,3,12,'(န) ၁။ တရား။','ဓဝ်သဳလ = သီလတရား။')
,(7641,3,12,'(န) ၁။ တရား။','ဓဝ်လောဘ = လောဘတရား။')
,(7641,3,12,'(န) ၁။ တရား။','၂။ အမှု။')
,(7641,3,12,'(န) ၁။ တရား။','ဓဝ်တလန် = လှည့်စားမှု။')
,(7641,3,12,'(န) ၁။ တရား။','ဓဝ်ပ္တေဟ် =ယုံကြည်မှု။ ယုံကြည်ချက်။')
,(7641,3,12,'(န) ၁။ တရား။','ဓဝ်မေထုန် = မေထုန်အမှု။')
,(7642,3,4,'၁။ ဖြောင့်မှန်သည်။ ဟုတ်မှန်သည်။ မလိမ်လည်။','“ပဟိုတ်ကဵုခမဳမွဲ ဟီုဟွံဓဝ်ဂှ်ရဘိမ္ဗသေဏဇာတ် ကျာ်တြဲတွံရ။” (ဇ—၈ဝ။ အစွောံ။) = “မဟုတ်မမှန်ပြောဆိုသော ရဟန်းတစ်ပါးကို အကြောင်းပြု၍ ဘီမသေနဇာတ်ကို မြတ်စွာဘုရားဟောတော်မူ၏။”')
,(7642,3,4,'၁။ ဖြောင့်မှန်သည်။ ဟုတ်မှန်သည်။ မလိမ်လည်။','“ဟီုကဵုဓဝ်၊ယာံဟီုဟွံဓဝ်တုဲ ဗှ်ေသ္ဒးအိုတ်လမျီုရ။” (ဇ—၄ဝ၂။ အစွောံ။) = “မှန်မှန်ပြော၊ မှန်မှန်မပြောပါက သင်အသက်ကုန်ရလိမ့်မည်။”')
,(7642,3,4,'၁။ ဖြောင့်မှန်သည်။ ဟုတ်မှန်သည်။ မလိမ်လည်။','၂။ (စကား) ရှေ့နောက်ညီသည်။')
,(7642,3,4,'၁။ ဖြောင့်မှန်သည်။ ဟုတ်မှန်သည်။ မလိမ်လည်။','“ပါၚ်တလအဲဟွံဓဝ်သွံ။” (ဇ—၈ဝ။ အစွောံ။) = “သင့်နှုတ်သည် (သင့်စကားသည်) ရှေ့နောက်မညီပါလား။”')
,(7642,3,4,'၁။ ဖြောင့်မှန်သည်။ ဟုတ်မှန်သည်။ မလိမ်လည်။','၃။ ပုံမှန်ပကတိဖြစ်သည်။ အချိန်အခါမှန်သည်။')
,(7642,3,4,'၁။ ဖြောင့်မှန်သည်။ ဟုတ်မှန်သည်။ မလိမ်လည်။','“ယြဴသၟိၚ်မွဲ ဗွဲစၟတ်ဂှ်ဟီုတုဲ ဗြဲဂူဓဝ်လောန်သန်ရ။ သၟိၚ်ဟီုမုသာတုဲ ဗြဲဂူဟွံဓဝ်ရ။” (ဇ—၄၂၂။ အစွောံ။) = “အကြင်မင်းသည် မှန်သောစကားကိုဆိုလျှင် ပုံမှန်ပကတိမိုးရွာ၏။ မင်းသည် မုသားကိုဆိုသည်ရှိသော် မိုးရွာမမှန်တော့။”')
,(7642,3,4,'၁။ ဖြောင့်မှန်သည်။ ဟုတ်မှန်သည်။ မလိမ်လည်။','“ဟိုတ်သၟိၚ်ဟွံတဴပ္ဍဲဓဝ်တုဲ ကျာပိုက်ဟွံဓဝ် ဗြဲဟွံဍာံ။” (ဇ—၅၂ဝ။ အစွောံ။) = “မင်းသည် တရား­မတည်သောကြောင့် လေတိုက်လည်းမမှန် မိုးလည်းအချိန်မမှန်။”')
,(7642,3,4,'၁။ ဖြောင့်မှန်သည်။ ဟုတ်မှန်သည်။ မလိမ်လည်။','၄။ တည့်သည်။ တည့်မတ်သည်။မတိမ်းစောင်း။')
,(7642,3,4,'၁။ ဖြောင့်မှန်သည်။ ဟုတ်မှန်သည်။ မလိမ်လည်။','“သၠဒကေဝ်ဂှ် တဴဓဝ်ဒၟံၚ်အကြာဝတ္ထုၜါဂှ်ရ။” = “ထိုချိန်ခွင်သည် ထိုဝတ္ထုနှစ်ခုအကြား­ တည့်မတ်စွာတည်နေ၏။”')
,(7643,3,6,'မျက်နှာချင်းဆိုင်။ တည့်တည့်။','“သ္ၚိညးနွံဓဝ်ကဵုသ္ၚိပိုဲရ။” = “သူ၏အိမ်သည် ကျွန်တော်တို့အိမ်နှင့် မျက်နှာချင်းဆိုင်တွင်ရှိသည်။”')
,(7643,3,6,'မျက်နှာချင်းဆိုင်။ တည့်တည့်။','“စိုပ်ဓဝ်ကဵုတၞံကြုက်ဂှ်တုဲ — ဗဒိုအ်လဝ်ဂၠုၚ်—။” (ဇ—၄ဝ၇။ အစွောံ။) = “သရက်ပၚ်နှင့်တည့်တည့်သို့ ရောက်သောအခါ လှေကိုရပ်ထားစေ၏။”')
,(7644,3,1,'စိတ်အလို။ နှလုံးအလို။','“(သေဋ္ဌဳ) သၟိက်ပလီုကၠေံ ဓဝ်စိုတ်လဗၚ်တံတုဲ ဂလာန်ဝွံမ္ဂး။” (ဇ—၅၃။ အစွောံ။) = “(သူဋ္ဌေးသည်) ထိုသေသောက်ကြူးတို့၏ နှလုံးအလိုကို ဖျက်ဆီးလိုသည်ဖြစ်၍— (ဤစကားကိုဆို၏။)” (ညောင်ကန်)')
,(7645,3,4,'တရားဟောခြင်းပြီးစီးသည်၊ အဆုံးသတ်သည်။','“တဲစှ်ပၚ်လ္ၚောဝ်၊ ပၚ်မှိၚ်ဓဝ်ကျာ်အဴ။ဇၟာပ်ဇန်အိုတ်တြုံဗြဴ၊ ဓဝ်စှ်ေစဴအာရ။” (လိက်ဂၞကျာ်ဝိသာခါ) = “လက်ဆယ်ဖြာမိုးရှိခိုးကာ ဘုရား၏တရားတော်ကို နာကြားကြကုန်၏၊ တရားဟောခြင်းပြီးစီးသောအခါ အားလုံးသောယောကျာ်းမိန်းမ လူအပေါင်းတို့သည် ပြန်သွားကြကုန်၏။”')
,(7646,3,1,'မာယာပရိယာယ်။ လှည့်စားမှု။',NULL)
,(7647,3,5,'၁။ တည့်တည့်။','‘အာဓဝ်ဓဝ်ညိ။’ = ‘တည့်တည့်သွားပါ။’')
,(7647,3,5,'၁။ တည့်တည့်။','၂။ မှန်မှန်။ အမှန်အတိုင်း။ မလိမ်မညာ။')
,(7647,3,5,'၁။ တည့်တည့်။','“မဟီုကဵုအဲဓဝ်ဓဝ်ညိ။” (ဇ—၅၃၁။ အစွောံ။) = “ငါ့ကို သၚ်မှန်မှန်ပြောပါ။”')
,(7647,3,5,'၁။ တည့်တည့်။','“ဟီုဓဝ်ဓဝ်ရ၊ လ္ပမုသာ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “အမှန်အတိုင်းပြောပါ၊ လိမ်ညာမုသားမဆိုနှင့်။”')
,(7648,3,1,'ယုံကြည်ချက်။ ယုံကြည်ရာတရား။',NULL)
,(7649,3,1,'မေထုန်အမှု။ မေထုန်အကျင့်။','“ပ္ဍဲဓဝ်မေထုန်ဂှ် ဆသွပ်လ္ပအ်ကီုလေဝ် အဲဟွံလ္ပအ်ညာတ်မွဲလှ်ေ။” (ဇ—၄၈၈။ အစွောံ။) = “အကျွန်ုပ်သည် အိပ်မက်ဖြင့်သော်လည်း မေထုန်အကျင့်ကို မမြင်မက်စဘူး။” (ညောင်ကန်)')
,(7650,3,1,'အဆွေခင်ပွန်းတရား။ အဆွေခင်ပွန်းတို့ ကျင့်ရာသောတရား။','“အသပ္ပရိုဟ်ဟွံတီဂုန်ညး မဒြိုဟ်ကဵုမိတ်ဝွံ ပလီုဓဝ်မိတ်တုဲရ။” (ဇ—၁၃၁။ အစွောံ။) = “ကျေးဇူးမသိသော မသူတော်သည် အဆွေခင်ပွန်းကိုပြစ်မှား၍ အဆွေခင်ပွန်းတရားကို ဖျက်ဆီးခဲ့ပြီ။”')
,(7651,3,4,'၁။ မှန်သည်။ ပုံမှန်ဖြစ်သည်။ ပကတိအတိုင်းဖြစ်သည်။','“ဗြဲဍာ်ဓဝ်ယာဒၟံၚ်ရဟာသၟိၚ်မ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “မိုးရေမှန်ပါ၏လော။”')
,(7651,3,4,'၁။ မှန်သည်။ ပုံမှန်ဖြစ်သည်။ ပကတိအတိုင်းဖြစ်သည်။','“ဗြဲဍာ်ဓဝ်ယာ ဍေံဂူအာဟွံသ္ဂုတ်ရကောန်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ချစ်သား၊ မိုးရေမှန်၍ မပြတ်ရွာသွန်း၏။”')
,(7651,3,4,'၁။ မှန်သည်။ ပုံမှန်ဖြစ်သည်။ ပကတိအတိုင်းဖြစ်သည်။','“ဟိုတ်နူညးဂမၠိုၚ် မဟွံဂွံတန်တဴပ္ဍဲဓဝ်တုဲဂှ် ကျာဝိတ္ထဳပိုက်ဟွံဓဝ်ယာ ဗြဲလေဝ်ဂူဟွံဓဝ်ယာကီုရ။” (အဓါန်မသုန်။ အစွောံ။) = “လူအပေါင်းတို့ တရား­မတည်သောကြောင့် လေတိုက်ရာလမ်းကြောင်းသည်မမှန်၊ မိုးရွာလည်းမမှန်တော့။”')
,(7651,3,4,'၁။ မှန်သည်။ ပုံမှန်ဖြစ်သည်။ ပကတိအတိုင်းဖြစ်သည်။','၂။ တရားမျှတသည်။ တရားနှင့်ညီသည်။ တရားဥပဒေစိုးမိုးသည်။')
,(7651,3,4,'၁။ မှန်သည်။ ပုံမှန်ဖြစ်သည်။ ပကတိအတိုင်းဖြစ်သည်။','“လၟုဟ်မိမွဲ၊ ကောအဲထောံလဝ်။ ဟးစက္ကဝဝ်၊ စိုတ်ဟွံဓဝ်ယာ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “နှမတော်တစ်ယောက်တည်းကို ပစ်ထားရစ်ခဲ့သော အို—မောင်တော်မင်းမြတ်၊ အရှင့်စိတ်သည် တရားမျှတမှုမရှိပါတကား။”')
,(7651,3,4,'၁။ မှန်သည်။ ပုံမှန်ဖြစ်သည်။ ပကတိအတိုင်းဖြစ်သည်။','“တရၚ်ဟွံဒးဒဝ် ဖျာဟွံဒးရုပ်၊ —ဍုၚ်ကွာန်ဓဝ်ယာ စိုပ်ကဵုလအိတ်ရ။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “တံခါးပိတ်စရာမလိုဈေးရုပ်သိမ်းစရာမလို မြို့ရွာသည် အလွန်အမင်း တရားဥပဒေစိုးမိုး၏။”')
,(7651,3,4,'၁။ မှန်သည်။ ပုံမှန်ဖြစ်သည်။ ပကတိအတိုင်းဖြစ်သည်။','“ယြဴပ္ဍဲကာလမွဲ တၠအဲဓဝ်ယာတုဲ သတ္တံဂမၠိုၚ် မတ္ၜိုဟ်စိုတ်ရ။ ယာံတၠအဲဟွံဓဝ်ယာမ္ဂး သတ္တံဂမၠိုၚ်မက္တဴရောၚ်” အမာတ်ဂးကဵုသၟိၚ်။ (သၠပတ်သတိပထာန်) = “အကြင်အခါ­ အရှင့်သားသည် တရားနှင့်ညီပါကလူသူအပေါင်းတို့သည် စိတ်အေးချမ်းသာကုန်၏။ အရှင့်သားသည် တရားနှင့်မညီပါက လူသူအပေါင်းတို့သည် ပူပန်ကြရကုန်၏” ဟုအမတ်သည် မင်းအားဆို၏။')
,(7652,3,1,'ရုပ်တရား။',NULL)
,(7653,3,1,'လူတို့၏အကျင့်။ ရွာသူတို့၏အကျင့်။ မေထုန်အမှု။','“ဒဒှ်ဣသိကဵုဂၞကျာ် မဒ္ဂေတ်ဓဝ်လိုက်ဂှ် ပြာကတ်အာကဵုညးဍုၚ်ဂမၠိုၚ်ရ။” (ဇ—၄၃၁။ အစွောံ။) = “ရသေ့၏မိဖုရားနှင့်တကွ လူတို့၏အကျင့်ကို မှီဝဲခြင်းသည် မြို့အလုံး­ ထင်ရှားစွာဖြစ်၏။” (ညောင်ကန်)')
,(7653,3,1,'လူတို့၏အကျင့်။ ရွာသူတို့၏အကျင့်။ မေထုန်အမှု။','“တိပိုန်သုဒိန် မသွိုန်ဗပိုန်ဓဝ်ပဝေဏဳလိုက် ပ္ဍဲသမ္ဘာတရေံဂှ်။” (သၠပတ်ဓမ္မသံဂိတိ) =“အရှင်သုဒိန်သည် မယားဟောင်း­ လူတို့၏မေထုန်အကျင့်ကို မှီဝဲ၏။”')
,(7654,3,1,'ပျင်းရိခြင်း။',NULL)
,(7655,3,1,'အကုသိုလ်တရား။',NULL)
,(7656,3,1,'သင်္ဂဟတရား။ စည်းရုံးသိမ်းသွင်းကြောင်းတရား။ (၁၊ ဒါန — ပေးကမ်းခြင်း။၂၊ ပီယဝါစာ — ချစ်ဖွယ်စကားဆိုခြင်း။ ၃၊ အတ္ထစရိယ — အကျိုးဆောင်ခြင်း။ ၄၊ သမာနတ္တတာ — မိမိနှင့် တန်းတူဆက်ဆံခြင်းဟူ၍ လေးပါးရှိသည်။) ဓဝ်သစ္စပန်ပြကာ (န) သစ္စာလေးပါး။ မြတ်စွာဘုရားဟောကြားသည့် မှန်ကန်သောတရားလေးပါး။ (၁၊ ဒုက္ခသစ္စာ — ဆင်းရဲအမှန်။ ၂၊ သမုဒယသစ္စာ — ဆင်းရဲကြောင်းအမှန်။ ၃၊ နိရောဓသစ္စာ — ဆင်းရဲငြိမ်းရာအမှန်။ ၄၊ မဂ္ဂသစ္စာ — ဆင်းရဲငြိမ်းကြောင်းအမှန်။) ဓဝ်သၟိၚ် (န) မင်းကျင့်တရား။','ဓဝ်သၟိၚ်စှ်ပြကာ = မင်းကျင့်တရားဆယ်ပါး။')
,(7657,3,16,'၂၊ သီလ = ပွမဒဂိုန်သဳမသုန်မဗိုန် (သီလဆောက်တည်ခြင်း) ၃၊ ပရိစ္စာဂ = ပွမသၠးဒြပ်ကဵုဒါန် (ဝါ) ပွမၞုံကဵုကွဵုကွေတ်သၠးပွး (ဝါ) ပွမၞုံကဵုထံက်ပၚ်ထောံကၠေံ။ (ပေးကမ်းစွန့်ကြဲခြင်း) ၄၊ အဇ္ဇဝ = ပွမၞုံကဵုစိုတ်တမ္ၚူ (ဖြောင့်မတ်မှန်ကန်စွာကျင့်ခြင်း) ၅၊ မဒ္ဒဝ = ပွမၞုံကဵုစိုတ်မဍိုန်ဍောတ်ပ္ဍဲသတ် ဟွံဂွံသ္ကာတ်မြဟ်ကြံကြ (ကိုယ်နှုတ်နှလုံး နူးညံ့သိမ်မွေ့ခြင်း) ၆၊ တပ = ပွမမၚ်သဳဥပုဟ် (ဥပုသ်ဆောက်တည်ခြင်း) ၇၊ အက္ကောဓ = ပွမဟွံဂွံဇၞော်ပၞတ် (အမျက်မထွက်ခြင်း) ၈၊ အဝိၚ်္ဟံသာ = ပွမဟွံဂွံပရိုက်ပျဲပျာံညး (မညှဉ်းဆဲခြင်း) ၉၊ ခန္တီ = ပွမအေၚ်ဒုၚ်လဟီုပြဝညး (သည်းခံခြင်း) ၁ဝ၊ အဝိရောဓန = ပွမဟွံဂွံထောံတၞောဝ်ဒ္ဂေတ်တၠပညာတမၠာတမၠာတေံ (ရှေးရှေးပညာရှိတို့၏ကျင့်စဉ်ကို မဆန့်ကျင်ခြင်း) ဓဝ်သၟတ်၊ ဓဝ်စၟတ် (န) အမှန်တရား။',NULL)
,(7658,3,1,'အရှက်အကြောက်တရား။ ဟိရိသြတ္တပ္ပတရား။',NULL)
;